function updateHome(){const total=store.data.completed.length;$('home-progress').textContent=total?total+' of 84 levels complete':'A journey from the beginning to dawn.';$('home-continue').hidden=!total&&!store.data.checkpoint;$('footer-save').textContent=store.status;}
