let trainingSpeed=1,trainingFrozen=false;
/** One fixed simulation tick of whatever is running; false stops the batch. */
function simTick():boolean{
        const frames=inputs.readAll();
        renderer.capture(world);
        if(replayPlayback)tickReplay();
        else if(scene){const f=world.fighters[0];A.step(scene,frames[f.inputId]||{});if(scene.checkpointEvent){const cp=scene.checkpointEvent;store.checkpoint(cp.level,cp.stage,cp.progress,cp.combatCleared,cp.seed,cp.seen||[]);}}
        else {S.step(world,frames);if(replayRecord&&replayRecord.entries.length<24000){replayRecord.entries.push({kind:'input',frames});S.maybeCheckpoint(replayRecord,world);}checkTutorial(frames);checkDrill();observeTraining(frames);}
        audio.play(world.events);
        if(scene&&scene.pendingCard!==null){showCard();return false;}
        return !(world.phase==='paused'||world.phase==='result'||scene?.phase==='complete'||scene?.phase==='failed');
}

// Controller/arrow-key menu navigation whenever gameplay input is not active.
const menuNav=new MenuNavigator();
menuNav.onBack=()=>{if(currentScreen==='levels')screen('chapters');else if(currentScreen!=='home'&&currentScreen!=='game')screen('home');};
bindArrowKeys(()=>!inputs.active);
function frame(now:number){if(!inputs.active)menuNav.poll(inputs.pads(),now);const dt=lastTime?now-lastTime:1000/60;lastTime=now;
  if(!world){inputs.readAll();if(now-lastControllerUpdate>400){updateControllers();lastControllerUpdate=now;}}
  if(world){
    const active=replayPlayback?replayIndex<replayPlayback.entries.length&&world.phase!=='result':scene?scene.phase==='active':world.phase==='playing'||world.phase==='countdown';
    if(active){
      // Training can run slower (wall-clock only; still exact 60 Hz ticks) or freeze for frame-stepping.
      const trainingOnly=!scene&&!replayPlayback&&world.mode==='training';
      const {sustained}=trainingOnly&&trainingFrozen?{sustained:false}:runner.advance(trainingOnly?dt*trainingSpeed:dt,simTick);
      if(sustained)pause('Performance pause');
    }else runner.reset();
    renderer.paint(world,scene,runner.accumulator/(1000/60),dt,active);if(world.tick-hudTick>=5||scene||world.phase==='result'){updateHud();hudTick=world.tick;}if((scene?.phase==='complete'||scene?.phase==='failed'||!scene&&world.phase==='result')&&!resultShown)showResult();
    if(now-lastControllerUpdate>400){updateControllers();lastControllerUpdate=now;}
  }
  // Portrait touch play: suggest rotating, but allow continuing.
$('rotate-continue').addEventListener('click',()=>document.documentElement.classList.add('portrait-ok'));
requestAnimationFrame(frame);
}
